-- Bengali training posters for lessons 8.5–8.7 (bn) — clean 1.10-style Safety / Grievance / Tariff cards
-- Lesson 8.5
UPDATE training_chapters
SET
  content = '{"level_id":"8.5","badge_name":"জরুরী রেগুলেশন (WBERC ফোকাস)","level_title":"সেফটি কোড (Safety Code): সুরক্ষার স্থানীয় আইন","mission_briefing":"এতক্ষণ আমরা টাকার হিসাব আর গ্রিডের কথা বললাম। এবার সবচেয়ে দামী জিনিসের কথা বলব—আপনার জীবন। ''সেফটি কোড'' কোনো সাধারণ বই নয়, এটি রক্ত দিয়ে লেখা অভিজ্ঞতা। CEA (Central Electricity Authority)-এর সেফটি রেগুলেশন এবং WBERC-এর নির্দেশিকা মিলিয়ে এই আইন তৈরি। এখানে ভুল করার কোনো ''রিটেক'' নেই। জানুন, আইন আপনাকে কীভাবে সুরক্ষা দেয় এবং আইনের চোখে আপনি কখন সুরক্ষিত।","sections":[{"title":"১. পারমিট টু ওয়ার্ক (PTW): আপনার আইনি কবচ","image_name":"/images/loader/safe85_ptw.webp","points":[{"item_name":"PTW ছাড়া কাজ নিষেধ","specifications":"৩৩ কেভি বা ১১ কেভি লাইনে কাজ করার আগে লিখিত পারমিট নেওয়া বাধ্যতামূলক।","importance":"পারমিট মানে হলো অথরাইজড পারসন লিখিত গ্যারান্টি দিচ্ছে যে লাইন বন্ধ এবং আর্থ করা আছে। পারমিট ছাড়া পোল-এ উঠলে এবং দুর্ঘটনা ঘটলে, কোম্পানি কোনো দায়িত্ব নেয় না।","daily_check":"পারমিট বইয়ের নম্বর এবং সময় মিলিয়ে দেখুন। ফোনে মুখের কথায় লাইন অফ আছে বিশ্বাস করবেন না।","image_name":"/images/loader/safe85_ptw.webp","image_caption":"PTW ছাড়া কাজ নিষেধ"},{"item_name":"LOTO (Lock Out Tag Out)","specifications":"ব্রেকার অফ করার পর হ্যান্ডেলে তালা লাগানো এবং ''কাজ চলছে'' বোর্ড ঝোলানো।","importance":"ভুল করে কেউ যেন ব্রেকার অন না করে দেয়, তার জন্য এই ব্যবস্থা।","image_name":"/images/loader/safe85_ptw.webp","image_caption":"LOTO · নিজের তালা · নিজের চাবি"}],"image_caption":"PTW · লিখিত পারমিট"},{"title":"২. ক্লিয়ারেন্স (Clearance): নিরাপদ দূরত্ব","image_name":"/images/loader/safe85_clearance.webp","points":[{"item_name":"গ্রাউন্ড ক্লিয়ারেন্স (Ground Clearance)","specifications":"রাস্তার ওপর দিয়ে যাওয়া লাইনের উচ্চতা। (যেমন: ১১ কেভি লাইনের জন্য মাটির থেকে অন্তত ১৮-১৯ ফুট উঁচুতে থাকতে হবে)।","importance":"গাড়ি বা মানুষ যেন তারে না ঠেকে। লাইন ঝুলে গেলে (Sagging) তা টাইট করা আপনার আইনি দায়িত্ব।","daily_check":"রাস্তায় ঘোরার সময় দেখুন কোনো তার বেশি ঝুলে আছে কি না।","image_name":"/images/loader/safe85_clearance.webp","image_caption":"১১kV · ১৮–১৯ ফুট"},{"item_name":"বিল্ডিং ক্লিয়ারেন্স","specifications":"বাড়ি বা বারান্দা থেকে তারের অনুভূমিক (Horizontal) দূরত্ব (যেমন: এলটি লাইনের জন্য ১.২ মিটার)।","importance":"কেউ যেন হাত বাড়িয়ে বা কাপড় মেলতে গিয়ে তারে না লাগে।","image_name":"/images/loader/safe85_clearance.webp","image_caption":"LT · অনুভূমিক ১.২ মি"}],"image_caption":"গ্রাউন্ড · বিল্ডিং ক্লিয়ারেন্স"},{"title":"৩. আর্থিং (Earthing): সেফটি কোডের মেরুদণ্ড","image_name":"/images/loader/safe85_earth.webp","points":[{"item_name":"চেইন আর্থিং / টেম্পোরারি আর্থিং","specifications":"লাইনের দুই প্রান্তে (কাজের জায়গার আগে ও পরে) ডিসচার্জ রড দিয়ে আর্থ করা।","importance":"আইন বলছে, ''Dead'' লাইনকেও ''Live'' মনে করতে হবে যতক্ষণ না সেটা আর্থ করা হচ্ছে। ব্যাক-ফিডিং বা ইন্ডাকশন ভোল্টেজ থেকে বাঁচতে এটাই একমাত্র উপায়।","daily_check":"পোলে ওঠার আগে নিজের হাতে আর্থিং রড ঝোলাবেন, অন্যকে বিশ্বাস করবেন না।","image_name":"/images/loader/safe85_earth.webp","image_caption":"Dead লাইনও Live মনে করুন"}],"image_caption":"চেইন আর্থিং · দুই প্রান্ত"}],"pro_tip":{"title":"ওস্তাদের মার (Pro Tips)","content":["১. সই করার আগে পড়ুন: পারমিট বই বা লগবুকে সই করার আগে পড়ে নিন কোন ফিডার, কোন সময় এবং কী কাজের জন্য পারমিট নেওয়া হচ্ছে।","২. নিজের তালা, নিজের চাবি: ব্রেকারে তালা লাগানোর পর চাবিটা নিজের পকেটে রাখুন। আপনার জীবন আপনার পকেটে।","৩. জুতো ও গ্লাভস: ছেঁড়া জুতো বা গ্লাভস পরে কাজ করা আর খালি হাতে কাজ করা একই ব্যাপার—দুটোই বেআইনি এবং বিপজ্জনক।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"এত বছর ধরে কাজ করছি, আমার পারমিট বা আর্থিং লাগে না, আমি হাত দিয়েই ভোল্টেজ বুঝি।","reality":"সবচেয়ে বড় ভুল! বিদ্যুৎ কাউকে চেনে না। পরিসংখ্যান বলে, নতুনদের চেয়ে অতি-আত্মবিশ্বাসী অভিজ্ঞ কর্মীরাই বেশি দুর্ঘটনার শিকার হয়।"},{"myth":"১১ কেভি লাইন ইনসুলেটেড থাকে, ধরলে কিছু হয় না।","reality":"ভুল। কভার্ড কন্ডাক্টর (Covered Conductor) হলেও তাকে বেয়ার (Bare) কন্ডাক্টর হিসেবেই ট্রিট করার আইন আছে। কারণ পিন-হোল বা ফাটল থাকতে পারে।"}],"image_name":"/images/loader/safe85_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · সেফটি কোড"},"advanced_section":{"title":"সেফটি রেগুলেশন ২০১০ (CEA)","facts":[{"title":"সেফটি অফিসার (Safety Officer)","content":"আইন অনুযায়ী প্রতিটি জোনে একজন ডেজিগনেটেড সেফটি অফিসার থাকার কথা, যিনি নিয়মিত সেফটি অডিট করবেন।"},{"title":"ইলেকট্রিক্যাল ইন্সপেক্টর (CEI Inquiry)","content":"কোনো মারাত্মক বৈদ্যুতিক দুর্ঘটনা ঘটলে পুলিশ কেস ছাড়াও ''চিফ ইলেকট্রিক্যাল ইন্সপেক্টর'' (CEI)-এর তদন্ত হয়। সেখানে যদি দেখা যায় সেফটি কোড মানা হয়নি (যেমন পারমিট ছিল না বা আর্থিং ছিল না), তবে লাইনম্যান এবং সুপারভাইজারের জেল পর্যন্ত হতে পারে।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '8.5' AND language = 'bn';

-- Lesson 8.6
UPDATE training_chapters
SET
  content = '{"level_id":"8.6","badge_name":"জরুরী রেগুলেশন (WBERC ফোকাস)","level_title":"গ্রাহক অভিযোগ নিষ্পত্তি (Grievance Redressal): আপনার কাজের পর্যালোচনা","mission_briefing":"ফিল্ডে কাজ করতে গেলে গ্রাহকের রাগ বা ক্ষোভের মুখে পড়াটা স্বাভাবিক। কেউ বিল নিয়ে রেগে আছে, কেউ ভোল্টেজ নিয়ে। কিন্তু মনে রাখবেন, আপনি তর্কের জায়গা নন। গ্রাহকের এই ক্ষোভ মেটানোর জন্য WBERC-এর তৈরি একটা শক্তিশালী আইনি কাঠামো আছে। একে বলে ''গ্রিভেন্স রিড্রেসাল মেকানিজম''। আজ আমরা জানব, গ্রাহক আসলে কোথায় নালিশ জানাতে পারে এবং সেখানে আপনার বা কোম্পানির ভূমিকা কী। এটা জানলে আপনি বুক ফুলিয়ে বলতে পারবেন—''স্যার, ঝগড়া না করে সঠিক জায়গায় কমপ্লেইন করুন, কাজ হবে।''","sections":[{"title":"১. কল সেন্টার ও ডকেট নম্বর: প্রথম ধাপ","image_name":"/images/loader/griev86_docket.webp","points":[{"item_name":"লিখিত অভিযোগের গুরুত্ব","specifications":"১৯১২ (টোল ফ্রি) বা কাস্টমার কেয়ার সেন্টারে (CCC) অভিযোগ জানানো।","importance":"মুখে বলা অভিযোগের কোনো দাম নেই। যতক্ষণ না ''ডকেট নম্বর'' বা ''কমপ্লেইন আইডি'' তৈরি হচ্ছে, ততক্ষণ আইনের চোখে কোনো সমস্যাই নেই।","daily_check":"গ্রাহক চেঁচামেচি করলে বিনয়ের সাথে জিজ্ঞাসা করুন—''দাদা, আপনি কি ডকেট করেছেন? নম্বরটা দিন, আমি দেখে নিচ্ছি।''","image_name":"/images/loader/griev86_docket.webp","image_caption":"ডকেট নম্বর = আইনি রেকর্ড"},{"item_name":"আপনার সুরক্ষা","specifications":"ডকেট ক্লোজ করার নিয়ম।","importance":"কাজ শেষ করে অফিসে রিপোর্ট না করা পর্যন্ত ডকেট ক্লোজ হয় না। আর ডকেট ওপেন থাকলে SoP-এর জরিমানা বাড়তে থাকে।","image_name":"/images/loader/griev86_docket.webp","image_caption":"কাজ শেষে ডকেট ক্লোজ"}],"image_caption":"১৯১২ · ডকেট নম্বর"},{"title":"২. CGRF (Consumer Grievance Redressal Forum)","image_name":"/images/loader/griev86_cgrf.webp","points":[{"item_name":"CGRF কী?","specifications":"প্রতিটি রিজিয়ন বা জোনে কোম্পানির তৈরি একটি বিশেষ আদালত।","importance":"কল সেন্টারে সমস্যার সমাধান না হলে গ্রাহক এখানে আবেদন করে। এখানে কোম্পানির অফিসারদের সাথে একজন নিরপেক্ষ সদস্যও থাকেন। এরা আইন মেনে রায় দেন।","daily_check":"CGRF-এর অর্ডারের কপি এলে সেটাকে সর্বোচ্চ গুরুত্ব দিয়ে কাজ করতে হয়।","image_name":"/images/loader/griev86_cgrf.webp","image_caption":"CGRF · ৪৫ দিনের রায়"}],"image_caption":"CGRF · রিজিয়নাল ফোরাম"},{"title":"৩. বিদ্যুৎ অম্বুডসম্যান (Ombudsman)","image_name":"/images/loader/griev86_ombuds.webp","points":[{"item_name":"সর্বোচ্চ বিচারক","specifications":"CGRF-এ খুশি না হলে গ্রাহক সরাসরি WBERC-এর অ্যাপয়েন্ট করা অম্বুডসম্যানের কাছে যায়।","importance":"এর রায় কোম্পানির এমডি (MD)-কেও মানতে হয়। এখানে কোম্পানির ভুল প্রমাণিত হলে বড় অঙ্কের ক্ষতিপূরণ দিতে হয়।","image_name":"/images/loader/griev86_ombuds.webp","image_caption":"অম্বুডসম্যান · MD-কেও মানতে হয়"}],"image_caption":"অম্বুডসম্যান · সর্বোচ্চ আপিল"}],"pro_tip":{"title":"ওস্তাদের মার (Pro Tips)","content":["১. রাগ ভাঙানোর কৌশল: গ্রাহক রেগে থাকলে তর্ক না করে বলুন, \"স্যার, আপনার অধিকার আছে CGRF-এ যাওয়ার। আপনি চাইলে আমি ফর্মটা এনে দিতে পারি।\" দেখবেন গ্রাহক শান্ত হয়ে গেছে।","২. রেকর্ড রাখুন: ফিল্ডে গিয়ে যদি দেখেন মিটার বা লাইনে সমস্যা নেই, কিন্তু গ্রাহক মিথ্যে অভিযোগ করছে, তবে তার ভিডিও বা ছবি তুলে রাখুন। শুনানির সময় এটাই প্রমাণ হবে।","৩. মিথ্যা প্রতিশ্রুতি দেবেন না: \"কালই হয়ে যাবে\"—এমন কথা বলবেন না যদি না আপনি নিশ্চিত হন। কথা দিয়ে কথা না রাখলে অভিযোগ আরও বড় আকার নেয়।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"আমাদের কোম্পানি সরকারি (বা বড় প্রাইভেট), আমাদের নামে কেস করে গ্রাহক কিছু করতে পারবে না।","reality":"ভুল ধারণা। WBERC এবং অম্বুডসম্যান গ্রাহক-বান্ধব। কোম্পানির গাফিলতি থাকলে তারা গ্রাহকের পক্ষেই রায় দেয় এবং কোম্পানিকে তা মানতেই হয়।"},{"myth":"লাইনম্যানের নামে কমপ্লেইন করলেই তার চাকরি যাবে।","reality":"না। যদি আপনি নিয়ম মেনে (SoP) কাজ করেন, তবে ভয়ের কিছু নেই। তদন্ত ছাড়া কারোর চাকরি যায় না।"}],"image_name":"/images/loader/griev86_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · গ্রিভেন্স"},"advanced_section":{"title":"আইনি সময়সীমা (Legal Timeline)","facts":[{"title":"৪৫ দিনের নিয়ম","content":"CGRF-কে অভিযোগ পাওয়ার ৪৫ দিনের মধ্যে রায় দিতে হয়। আর অম্বুডসম্যানের ক্ষেত্রে সময়সীমা সাধারণত ৬০ থেকে ৯০ দিন।"},{"title":"ক্ষতিপূরণ পাওয়ার অধিকার","content":"WBERC রেগুলেশন অনুযায়ী, যদি প্রমাণ হয় যে কোম্পানি অযথারীতি গ্রাহককে হয়রান করেছে, তবে অম্বুডসম্যান ১ লক্ষ টাকা পর্যন্ত ক্ষতিপূরণ (Compensation) দেওয়ার নির্দেশ দিতে পারে।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '8.6' AND language = 'bn';

